// Find the "Change to English" link in the notification banner
const englishLink = document.querySelector('#slim_appbar a[href*="hl=en"]');
if (!englishLink) return;

// Avoid duplicating the button
if (document.getElementById('ext-change-to-english-btn')) return;

const btn = document.createElement('a');
btn.id = 'ext-change-to-english-btn';
btn.href = englishLink.href;
btn.textContent = '🌐 Change to English';
btn.title = 'Switch to globally available English search results';

Object.assign(btn.style, {
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  marginLeft: '10px',
  padding: '0 18px',
  height: '44px',
  background: '#1a73e8',
  color: '#fff',
  fontFamily: 'Google Sans, Roboto, Arial, sans-serif',
  fontSize: '14px',
  fontWeight: '600',
  letterSpacing: '0.01em',
  borderRadius: '24px',
  border: 'none',
  cursor: 'pointer',
  textDecoration: 'none',
  whiteSpace: 'nowrap',
  boxShadow: '0 1px 3px rgba(26,115,232,0.4)',
  flexShrink: '0',
  transition: 'background 0.15s, box-shadow 0.15s',
  verticalAlign: 'middle',
});

btn.addEventListener('mouseover', () => {
  btn.style.background = '#1557b0';
  btn.style.boxShadow = '0 2px 6px rgba(26,115,232,0.5)';
});
btn.addEventListener('mouseout', () => {
  btn.style.background = '#1a73e8';
  btn.style.boxShadow = '0 1px 3px rgba(26,115,232,0.4)';
});

// Insert right after the search bar container
element.insertAdjacentElement('afterend', btn);
